def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        base = 18.0 if hp > 3 else 32.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    prev_high = 0.0
    prev_live_high = 0.0
    desperate_count = 0
    rich_aggressive = 0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if isinstance(prev, dict):
            bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            if bid > prev_high:
                prev_high = bid
            if bid > prev_live_high:
                prev_live_high = bid
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 500 and bid is not None and bid >= 60:
            rich_aggressive += 1

    tight_supply = supply <= 17.0
    ample_supply = supply >= 22.0
    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2
    if tight_supply:
        danger += 1
    if desperate_count >= 2:
        danger += 1

    if prev_bids:
        anchor = prev_live_high + 1.25
    else:
        anchor = 42.0

    if danger >= 5:
        bid = max(anchor, 88.0)
    elif danger >= 3:
        bid = max(anchor * 0.92, 68.0)
    elif danger >= 1:
        bid = max(anchor * 0.72, 46.0)
    else:
        bid = 28.0 if ample_supply else 34.0

    if rich_aggressive >= 2 and hp > 4 and no_water_days == 0:
        bid = min(bid, 36.0 if ample_supply else 42.0)

    if day >= 8:
        bid += 8.0
    elif day >= 5 and danger >= 2:
        bid += 4.0

    reserve_days = 2 if hp > 3 else 1
    reserve = DAILY_SALARY * reserve_days
    max_affordable = budget - reserve
    if max_affordable < 0:
        max_affordable = budget

    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return max(0.1, min(my_current_budget, 1.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    HIGH_COMPETITION_THRESHOLD = DAILY_SALARY * 0.75
    CRITICAL_HP_THRESHOLD = 2
    LOW_HP_THRESHOLD = 4
    GOOD_HP_THRESHOLD = 5

    bid_if_critical_hp = DAILY_SALARY * 0.95
    bid_if_low_hp = DAILY_SALARY * 0.8
    bid_if_healthy_low_comp = DAILY_SALARY * 0.55
    bid_if_healthy_high_comp = DAILY_SALARY * 0.4 # Strategic saving if healthy and high competition
    bid_increment = 5.0

    calculated_bid = 0.0

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= HIGH_COMPETITION_THRESHOLD:
            if my_current_hp > GOOD_HP_THRESHOLD:
                calculated_bid = bid_if_healthy_high_comp
            else:
                calculated_bid = max(highest_prev_bid + bid_increment, bid_if_low_hp)
        else:
            if my_current_hp <= CRITICAL_HP_THRESHOLD:
                calculated_bid = bid_if_critical_hp
            elif my_current_hp <= LOW_HP_THRESHOLD:
                calculated_bid = bid_if_low_hp
            else:
                calculated_bid = max(highest_prev_bid + bid_increment, bid_if_healthy_low_comp)
    else:
        if my_current_hp <= CRITICAL_HP_THRESHOLD:
            calculated_bid = bid_if_critical_hp
        elif my_current_hp <= LOW_HP_THRESHOLD:
            calculated_bid = bid_if_low_hp
        else:
            calculated_bid = bid_if_healthy_low_comp

    final_bid = max(0.1, calculated_bid)
    final_bid = min(my_current_budget, final_bid)

    if current_day >= EPISODE_DAYS - 2 and my_current_budget > DAILY_SALARY * 1.5 and my_current_hp > CRITICAL_HP_THRESHOLD:
        final_bid = max(final_bid, DAILY_SALARY * 0.7)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
